#!/usr/bin/env python3
import argparse,csv,html
from collections import Counter
from datetime import datetime,timezone
from pathlib import Path
SEVS=['Critical','High','Medium','Low','Warning','Note','Error','N/A']
def rows(p):
 with Path(p).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def e(x):return html.escape(str(x or ''))
def sev(r):
 x=(r.get('Security Severity') or '').strip();return x.title() if x and x.lower()!='n/a' else (r.get('Severity') or 'N/A').title()
def main():
 p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--output',required=True);p.add_argument('--title',default='CodeQL C/C++ Security Portal');p.add_argument('--classification',default='Confidential - Security');p.add_argument('--report-pdf',default='codeql-cpp-alerts.pdf');p.add_argument('--report-csv',default='codeql-cpp-alerts.csv');p.add_argument('--history',action='append',nargs=2,default=[]);a=p.parse_args();rs=rows(a.input);c=Counter(sev(r) for r in rs);st=Counter(r.get('Status','Unknown') for r in rs);mx=max([c[x] for x in SEVS]+[1]);bars=''.join(f'<div class="bar"><b>{e(s)}</b><span><i style="width:{max(4,int(c[s]/mx*100))}%"></i></span><b>{c[s]}</b></div>' for s in SEVS if c[s]);chips=''.join(f'<span class="chip">{e(k)} <b>{v}</b></span>' for k,v in sorted(st.items(),key=lambda x:(-x[1],x[0])));hist=''.join(f'<li><a href="{e(l)}">{e(n)}</a></li>' for n,l in a.history) or '<li>No history.</li>';trs=''.join(f'<tr><td>{e(r["Alert ID"])}</td><td><code>{e(r["Rule ID"])}</code></td><td class="{e(sev(r)).lower()}">{e(sev(r))}</td><td>{e(r["File"])}:{e(r["Start Line"])}</td><td>{e(r["Status"])}</td><td>{e(r["Assignee / Owner"])}</td><td>{e(r["Dismissed By"])}</td><td>{e(r["Dismissal Reason"])}</td><td>{e(r["Triage Comment"])}</td><td><a href="{e(r["Alert URL"])}" target="_blank" rel="noopener">Alert</a></td></tr>' for r in rs);doc=f"""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(a.title)}</title><style>:root{{--bg:#f5f7fa;--card:#fff;--ink:#101828;--muted:#667085;--line:#d0d5dd}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:14px Segoe UI,Arial}}header{{background:#101828;color:#fff;padding:28px 5vw}}header h1{{margin:0 0 7px;font-size:28px}}header p{{color:#d0d5dd}}main{{max-width:1550px;margin:25px auto;padding:0 24px}}.cards{{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}}.card,.panel{{background:#fff;border:1px solid var(--line);border-radius:12px;padding:18px}}.metric{{font-size:30px;font-weight:750}}.muted{{color:var(--muted);font-size:12px}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}}.bar{{display:grid;grid-template-columns:90px 1fr 35px;gap:10px;align-items:center;margin:11px 0}}.bar span{{height:14px;background:#eaecf0;border-radius:10px;overflow:hidden}}.bar i{{display:block;height:100%;background:#475467}}.chip{{display:inline-block;border:1px solid var(--line);border-radius:20px;padding:8px 12px;margin:4px;background:#f9fafb}}.btn{{display:inline-block;padding:11px 16px;margin:18px 8px 18px 0;border-radius:8px;background:#101828;color:#fff;text-decoration:none;font-weight:650}}.alt{{background:#fff;color:#101828;border:1px solid var(--line)}}.table{{overflow:auto}}table{{border-collapse:collapse;width:100%;min-width:1450px;background:#fff}}th,td{{border-bottom:1px solid var(--line);padding:9px 8px;text-align:left;vertical-align:top;font-size:12px}}th{{background:#f2f4f7;position:sticky;top:0}}.critical{{color:#b42318;font-weight:700}}.high{{color:#d92d20;font-weight:700}}.medium{{color:#b54708;font-weight:700}}.low{{color:#027a48;font-weight:700}}footer{{max-width:1550px;margin:25px auto;padding:0 24px 40px;color:var(--muted);font-size:12px}}@media(max-width:900px){{.cards{{grid-template-columns:repeat(2,1fr)}}.grid{{grid-template-columns:1fr}}}}</style></head><body><header><h1>{e(a.title)}</h1><p>{e(a.classification)} · {datetime.now(timezone.utc):%Y-%m-%d %H:%M UTC}</p></header><main><a class="btn" href="{e(a.report_pdf)}">Download PDF</a><a class="btn alt" href="{e(a.report_csv)}">Download CSV</a><section class="cards"><div class="card"><div class="metric">{len(rs)}</div><div class="muted">Total findings</div></div><div class="card"><div class="metric">{c['Critical']}</div><div class="muted">Critical</div></div><div class="card"><div class="metric">{c['High']}</div><div class="muted">High</div></div><div class="card"><div class="metric">{c['Medium']}</div><div class="muted">Medium</div></div><div class="card"><div class="metric">{c['Low']}</div><div class="muted">Low</div></div></section><div class="grid"><section class="panel"><h2>Severity distribution</h2>{bars or '<p>No findings.</p>'}</section><section class="panel"><h2>Triage status</h2>{chips or '<p>No findings.</p>'}</section></div><section class="panel" style="margin-top:18px"><h2>Historical reports</h2><ul>{hist}</ul></section><section class="panel" style="margin-top:18px"><h2>Finding details</h2><div class="table"><table><thead><tr><th>Alert</th><th>Rule</th><th>Severity</th><th>Location</th><th>Status</th><th>Assignee / Owner</th><th>Dismissed By</th><th>Reason</th><th>Triage Comment</th><th>GitHub</th></tr></thead><tbody>{trs or '<tr><td colspan="10">No findings.</td></tr>'}</tbody></table></div></section></main><footer>Generated from GitHub Code Scanning / CodeQL REST API. Treat as confidential security information.</footer></body></html>""";Path(a.output).parent.mkdir(parents=True,exist_ok=True);Path(a.output).write_text(doc,encoding='utf-8')
if __name__=='__main__':main()
